// One-stage shift register stage, with enable, register load, and async
// register feed-forward. The register feeds back to the input, so the
// long-path delay is independent of the register delay -> lower Fmax.
module TopModule(input clk, input w, input R, input E, input L, output reg Q);
    reg [1:0] D;
    always @(posedge clk) begin
        if (L) D[0] <= R;
        if (E) D[1] <= D[0];
        if (E) Q <= D[1];
    end
endmodule

