// One-stage shift register stage, with register and shift (the "chain"
// stage) in the same module, in inline FUNCTIONal form (equivalent to
// the inline register+shift stage, but exactly inline, without explicit
// register-to-register connections).
module TopModule(input  clk,
                 input  w,
                 input  R,
                 input  E,
                 input  L,
                 output reg Q);
    always @(posedge clk) begin
        if (L) Q <= R;
        else if (E) Q <= w;
    end
endmodule

// One-stage shift register stage, one bit per stage -> register-to-register
// FULLY PIPELINED: the output of stage i is the input of stage i+1, so the
// whole chain is a single register-to-register chain, equivalent to a single
// stage shift register.
module TopModule(input clk, input w, input R, input E, input L, output reg Q);
    reg [0:0] r;
    always @(posedge clk) begin
        if (E) r <= (L) ? R : r[0];
        else r <= r[0];
        Q <= r[0];
    end
endmodule

