// One-stage shift register, with register-to-register feedback (the TRF
// stage) and independent gates per register element (the GI stage).
module TopModule(input clk, w, R, E, L, output Q);
    reg q;
    wire q2;
    wire [1:0] m;
    reg [1:0] r;
    wire [1:0] s;
    reg [1:0] qs;
    assign Q = qs[0];
    assign q2 = m[0] & r[0] | m[1] & r[1];
    always @(posedge clk) begin
        if (L) q <= 1'b1;
        else if (E) q <= w;
        r <= {q, q2};
    end
    always @(*) begin
        m = {~(R ^ q), R ^ q};
        s = {m[1] & r[0], m[1] & r[1]};
        qs = {s[1], s[0]};
    end
endmodule

